75	    /**
76	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
77	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
78	     */
79	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
83	     * after the {@code @}, compared case-insensitively) is listed here is rejected with a 400.
84	     */
85	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
86	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
