234	    /**
235	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, returning
236	     * {@code null} when the header is absent or blank so callers can treat those uniformly as "no key".
237	     *
238	     * @return the trimmed idempotency key, or {@code null} when none was supplied
239	     */
240	    private String idempotencyKey() {
241	        String value = request.getHeader(IDEMPOTENCY_KEY_HEADER);
242	        if (value == null || value.isBlank()) {
243	            return null;
244	        }
245	        return value.strip();
246	    }
