343	    /**
344	     * Counts how many existing owners share the given first and last name, compared
345	     * case-insensitively, at the moment before the new owner is persisted. The result is
346	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
347	     * stood when the owner was created rather than being recomputed on later reads.
348	     *
349	     * @param firstName the first name of the owner being created
350	     * @param lastName the last name of the owner being created
351	     * @return the number of pre-existing owners with the same first and last name
352	     */
353	    private int countNamesakes(String firstName, String lastName) {
354	        String first = firstName == null ? "" : firstName;
355	        String last = lastName == null ? "" : lastName;
356	        return (int) this.clinicService.findAllOwners().stream()
357	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
358	                && last.equalsIgnoreCase(existing.getLastName()))
359	            .count();
360	    }
361	
362	    /**
363	     * Builds the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'} where
364	     * {@code REGION} is the region code derived from the owner's postcode (see {@link #deriveRegion})
365	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
366	     * normalized telephone concatenated with the last name. For example an owner in the NSW postcode
367	     * range gets a code such as {@code 'NSW-3F2A1B9C'}.
368	     *
369	     * <p>When the computed code collides with an existing owner's customer code, it is de-duplicated
370	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result
371	     * unique across all existing owners' customer codes. The de-duplicated code is what gets assigned.
372	     *
373	     * @param owner the owner being created, whose postcode, city and last name feed the code
374	     * @param normalizedTelephone the owner's E.164-normalized telephone
375	     * @return the assigned customer code, de-duplicated against existing owners if necessary
376	     */
377	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
378	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
379	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
380	        String hash8 = sha256Hex8(normalizedTelephone + lastName);
381	        String baseCode = region + "-" + hash8;
382	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
383	            .map(Owner::getCustomerCode)
384	            .filter(code -> code != null)
385	            .collect(java.util.stream.Collectors.toSet());
386	        if (!existingCodes.contains(baseCode)) {
387	            return baseCode;
388	        }
389	        int n = 2;
390	        while (existingCodes.contains(baseCode + "-" + n)) {
391	            n++;
392	        }
393	        return baseCode + "-" + n;
394	    }
395	
396	    /**
397	     * Derives an owner's region code, preferring the postcode: the region whose {@link #REGION_POSTCODES}
398	     * range contains the (4-digit) postcode is returned, falling back to the fixed {@link #CITY_REGION}
399	     * city table when the postcode is absent or in no known range, and finally to {@code "UNKNOWN"}.
400	     *
401	     * @param postcode the owner's postcode, may be {@code null}
402	     * @param city the owner's city, used to resolve the region when the postcode does not
403	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
404	     */
405	    private String deriveRegion(String postcode, String city) {
406	        if (postcode != null) {
407	            try {
408	                int value = Integer.parseInt(postcode.trim());
409	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
410	                    int[] range = entry.getValue();
411	                    if (value >= range[0] && value <= range[1]) {
412	                        return entry.getKey();
413	                    }
414	                }
415	            } catch (NumberFormatException ex) {
416	                // Not a numeric postcode; fall back to the city table below.
417	            }
418	        }
419	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
420	    }
421	
422	    /**
423	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
424	     * given input's UTF-8 bytes.
425	     *
426	     * @param input the string to hash
427	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
428	     */
429	    private String sha256Hex8(String input) {
430	        try {
431	            byte[] digest = MessageDigest.getInstance("SHA-256")
432	                .digest(input.getBytes(StandardCharsets.UTF_8));
433	            StringBuilder hex = new StringBuilder();
434	            for (int i = 0; i < 4; i++) {
435	                hex.append(String.format("%02X", digest[i]));
436	            }
437	            return hex.toString();
438	        } catch (NoSuchAlgorithmException ex) {
439	            throw new IllegalStateException("SHA-256 not available", ex);
440	        }
441	    }
442	
443	    /**
444	     * Rejects an owner payload that is missing or blank in any of the required fields
445	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
446	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
447	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
448	     * guard enforces the rule uniformly for every required field.
449	     *
450	     * @param ownerFieldsDto the submitted owner payload
451	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
452	     */
453	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
454	        List<String> invalidFields = new ArrayList<>();
455	        if (isBlank(ownerFieldsDto.getFirstName())) {
456	            invalidFields.add("firstName");
457	        }
458	        if (isBlank(ownerFieldsDto.getLastName())) {
459	            invalidFields.add("lastName");
460	        }
461	        if (isBlank(ownerFieldsDto.getAddressLine1())
462	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
463	            invalidFields.add("address");
464	        }
465	        if (isBlank(ownerFieldsDto.getCity())) {
466	            invalidFields.add("city");
467	        }
468	        if (isBlank(ownerFieldsDto.getTelephone())) {
469	            invalidFields.add("telephone");
470	        }
471	        if (!invalidFields.isEmpty()) {
472	            throw new InvalidOwnerFieldsException(invalidFields);
473	        }
474	    }
475	
476	    private boolean isBlank(String value) {
477	        return value == null || value.isBlank();
478	    }
479	
480	    /**
481	     * Whether an existing owner has been soft-deleted. A soft-deleted owner retains its row but is
482	     * excluded from the create endpoint's duplicate and identity checks, so it never blocks the
483	     * creation of a new owner. A {@code null} flag (an owner predating the soft-delete column) is
484	     * treated as not deleted.
485	     *
486	     * @param owner an existing owner
487	     * @return {@code true} if the owner is flagged deleted
488	     */
489	    private boolean isDeleted(Owner owner) {
490	        return Boolean.TRUE.equals(owner.getDeleted());
491	    }
492	
493	    /**
494	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
495	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
496	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
497	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
498	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
499	     * and returned exactly as given.
500	     *
501	     * @param postcode the submitted postcode, may be {@code null} when absent
502	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
503	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
504	     */
505	    private void validatePostcode(String postcode, String city) {
506	        if (postcode == null) {
507	            return;
508	        }
509	        if (!postcode.matches("[0-9]{4}")) {
510	            throw new InvalidOwnerFieldsException(List.of("postcode"));
511	        }
512	        String region = city == null ? null : CITY_REGION.get(city);
513	        if (region == null) {
514	            return;
515	        }
516	        int[] range = REGION_POSTCODES.get(region);
517	        int value = Integer.parseInt(postcode);
518	        if (value < range[0] || value > range[1]) {
519	            throw new InvalidOwnerFieldsException(List.of("postcode"));
520	        }
521	    }
522	
523	    /**
524	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
525	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
526	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
527	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
528	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
529	     *
530	     * @param telephone the raw telephone value from the submitted owner payload
531	     * @return the normalized E.164 telephone number
532	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
533	     */
534	    private String normalizeTelephone(String telephone) {
535	        String raw = telephone == null ? "" : telephone.strip();
536	        boolean hasCountryCode = raw.startsWith("+");
537	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
538	        String digits;
539	        if (hasCountryCode) {
540	            digits = cleaned.substring(1);
541	        } else {
542	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
543	            digits = "61" + national;
544	        }
545	        if (!digits.matches("[0-9]{8,15}")) {
546	            throw new InvalidOwnerFieldsException(List.of("telephone"));
547	        }
548	        validateNationalNumberLength(digits);
549	        return "+" + digits;
550	    }
551	
552	    /**
553	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
554	     * country calling code) has the exact length required for that country. The country code is matched
555	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
556	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
557	     *
558	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
559	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
560	     */
561	    private void validateNationalNumberLength(String digits) {
562	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
563	            String countryCode = entry.getKey();
564	            if (digits.startsWith(countryCode)) {
565	                int nationalLength = digits.length() - countryCode.length();
566	                if (nationalLength != entry.getValue()) {
567	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
568	                }
569	                return;
570	            }
571	        }
572	    }
573	
574	    /**
575	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
576	     * returning {@code null} when the value cannot form a valid E.164 number.
577	     *
578	     * @param telephone an existing owner's stored telephone value
579	     * @return the E.164 form, or {@code null} if it cannot be normalized
580	     */
581	    private String toE164OrNull(String telephone) {
582	        try {
583	            return normalizeTelephone(telephone);
584	        } catch (InvalidOwnerFieldsException ex) {
585	            return null;
586	        }
587	    }
588	
589	    /**
590	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
591	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
592	     * accepted value is trimmed and lower-cased before it is stored and returned.
593	     *
594	     * @param email the raw email value from the submitted owner payload, may be {@code null}
595	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
596	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
597	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
598	     */
599	    private String normalizeEmail(String email) {
600	        if (email == null) {
601	            return null;
602	        }
603	        String trimmed = email.strip();
604	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
605	            throw new InvalidOwnerFieldsException(List.of("email"));
606	        }
607	        String normalized = trimmed.toLowerCase(Locale.ROOT);
608	        String domain = normalized.substring(normalized.indexOf('@') + 1);
609	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
610	            throw new InvalidOwnerFieldsException(List.of("email"));
611	        }
612	        return normalized;
613	    }
614	
615	    /**
616	     * Rejects creating an owner whose derived identity key
617	     * ({@code '<normalizedTelephone>|<email>|<householdId>'}, see {@link OwnerMapper#identityKey})
618	     * exactly equals that of an existing non-deleted owner. Two owners are treated as duplicates only
619	     * when their whole identity keys match, so members of the same household (same {@code householdId})
620	     * who differ in telephone or email are not duplicates and are admitted as additional household
621	     * members. Such an owner is rejected with a 409, <em>unless</em> the request opts into
622	     * {@code sharesHousehold}, which bypasses the block entirely.
623	     *
624	     * @param owner the owner being created, whose identity key is matched
625	     * @param sharesHousehold whether the request declared the owner a shared-household member
626	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key
627	     */
628	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
629	        if (sharesHousehold) {
630	            return;
631	        }
632	        String identityKey = ownerMapper.identityKey(owner);
633	        boolean duplicate = this.clinicService.findAllOwners().stream()
634	            .filter(existing -> !isDeleted(existing))
635	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
636	        if (duplicate) {
637	            throw new DuplicateOwnerIdentityException(identityKey);
638	        }
639	    }
640	
641	    /**
642	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
643	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
644	     * owner that is not a hard duplicate but shares an existing owner's last name (compared
645	     * case-insensitively, see {@link #normalizeForComparison}) and postcode while carrying a <em>different</em>
646	     * telephone. When such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
647	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
648	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
649	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
650	     *
651	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the household
652	     * duplicate block) is never a <em>suspected</em> duplicate: it is knowingly created as another member
653	     * of the household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
654	     * {@code null} without consulting the existing population.
655	     *
656	     * @param owner the owner being created, whose last name and postcode are matched
657	     * @param normalizedTelephone the E.164 telephone of the owner being created
658	     * @param sharesHousehold whether the request declared the owner a shared-household member
659	     */
660	    private void assignPossibleDuplicate(Owner owner, String normalizedTelephone, boolean sharesHousehold) {
661	        if (sharesHousehold) {
662	            owner.setPossibleDuplicateOf(null);
663	            owner.setPossibleDuplicate(false);
664	            return;
665	        }
666	        String postcode = owner.getPostcode();
667	        Integer matchId = null;
668	        if (postcode != null) {
669	            String lastName = normalizeForComparison(owner.getLastName());
670	            for (Owner existing : this.clinicService.findAllOwners()) {
671	                if (!isDeleted(existing)
672	                    && postcode.equals(existing.getPostcode())
673	                    && lastName.equals(normalizeForComparison(existing.getLastName()))
674	                    && !normalizedTelephone.equals(toE164OrNull(existing.getTelephone()))
675	                    && existing.getId() != null
676	                    && (matchId == null || existing.getId() < matchId)) {
677	                    matchId = existing.getId();
678	                }
679	            }
680	        }
681	        owner.setPossibleDuplicateOf(matchId);
682	        owner.setPossibleDuplicate(matchId != null);
683	    }
684	
685	    /**
686	     * The maximum number of owners a single city may contain. Once a city already holds this many
687	     * owners, creating another owner in that city is rejected.
688	     */
689	    private static final int MAX_OWNERS_PER_CITY = 50;
690	
691	    /**
692	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
693	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
694	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
695	     * counting used elsewhere.
696	     *
697	     * @param city the city of the owner being created
698	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
699	     */
700	    /**
701	     * The maximum number of owners that may be registered on a single day. Once this many owners
702	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
703	     */
704	    private static final int MAX_OWNERS_PER_DAY = 100;
705	
706	    /**
707	     * Fixed list of public holidays. A registration date that lands on one of these dates is not a
708	     * business day and is rolled forward to the next non-holiday weekday.
709	     */
710	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
711	        LocalDate.of(2026, 1, 1),
712	        LocalDate.of(2026, 1, 26),
713	        LocalDate.of(2026, 4, 25),
714	        LocalDate.of(2026, 12, 25),
715	        LocalDate.of(2026, 12, 28));
716	
717	    /**
718	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
719	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
720	     * registration date of the owner being created.
721	     *
722	     * @param registrationDate the registration date of the owner being created
723	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
724	     */
725	    /**
726	     * Rolls an effective registration date forward onto a business day. A registration date must fall
727	     * on a weekday that is not a public holiday: when the supplied or defaulted date is a Saturday, a
728	     * Sunday, or a listed public holiday it is rolled forward one day at a time until it reaches the
729	     * next non-holiday business day, and that adjusted date becomes the owner's {@code registrationDate}.
730	     * A date that is already a non-holiday weekday is returned unchanged. Every value derived from the
731	     * registration date (the daily create-limit count, the membership number's year segment, and so on)
732	     * uses this adjusted date.
733	     *
734	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
735	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
736	     */
737	    /**
738	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
739	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
740	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
741	     * against the date exactly as supplied, before it is rolled forward onto a business day.
742	     *
743	     * @param registrationDate the registration date supplied in the request, may be {@code null}
744	     * @throws FutureRegistrationDateException if the supplied date is after the server date
745	     */
746	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
747	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
748	            throw new FutureRegistrationDateException(registrationDate);
749	        }
750	    }
751	
752	    private LocalDate rollToBusinessDay(LocalDate date) {
753	        LocalDate adjusted = date;
754	        while (!isBusinessDay(adjusted)) {
755	            adjusted = adjusted.plusDays(1);
756	        }
757	        return adjusted;
758	    }
759	
760	    private boolean isBusinessDay(LocalDate date) {
761	        DayOfWeek day = date.getDayOfWeek();
762	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
763	            return false;
764	        }
765	        return !PUBLIC_HOLIDAYS.contains(date);
766	    }
767	
768	    private void rejectDailyLimitReached(LocalDate registrationDate) {
769	        long ownersToday = this.clinicService.findAllOwners().stream()
770	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
771	            .count();
772	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
773	            throw new DailyOwnerLimitExceededException(registrationDate);
774	        }
775	    }
776	
777	    /**
778	     * The number of owners that must already share a {@code registrationDate} before a newly created
779	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
780	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
781	     */
782	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
783	
784	    /**
785	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
786	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
787	     * the same registration date at the time this owner is created. Existing owners are counted by their
788	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
789	     * daily create-limit accumulation.
790	     *
791	     * @param registrationDate the registration date of the owner being created
792	     * @return {@code true} if the day already holds more than the threshold number of owners
793	     */
794	    private boolean isBulkSignupDay(LocalDate registrationDate) {
795	        long ownersToday = this.clinicService.findAllOwners().stream()
796	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
797	            .count();
798	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
799	    }
800	
801	    private void rejectCityAtCapacity(String city) {
802	        String normalizedCity = normalizeForComparison(city);
803	        long ownersInCity = this.clinicService.findAllOwners().stream()
804	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
805	            .count();
806	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
807	            throw new OwnerCityCapacityExceededException(city);
808	        }
809	    }
810	
811	    /**
812	     * Counts how many owners belong to the household the owner being created has just been assigned to,
813	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
814	     * given identifier; the owner being created is added on because it is counted before being persisted.
815	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
816	     * household of one. The value is snapshotted on the owner.
817	     *
818	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
819	     * @return the number of household members, including the owner being created
820	     */
821	    private int countHousehold(String householdId) {
822	        if (householdId == null) {
823	            return 1;
824	        }
825	        long existing = this.clinicService.findAllOwners().stream()
826	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
827	            .count();
828	        return (int) existing + 1;
829	    }
830	
831	    /**
832	     * Computes the membership-level ceiling for the owner being created, snapshotted at creation time.
833	     * A new owner's membership level cannot exceed one above the current maximum membership level among
834	     * their existing household members: the returned cap is that maximum plus one. Existing household
835	     * members are the non-deleted owners already carrying the same {@code householdId}, and their
836	     * membership level is their effective (already-capped) {@link OwnerMapper#membershipLevel level}.
837	     * Returns {@code null} when there is no existing household member, in which case no cap applies.
838	     *
839	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
840	     * @return one above the highest household member's membership level, or {@code null} when none exist
841	     */
842	    private Integer membershipLevelCap(String householdId) {
843	        if (householdId == null) {
844	            return null;
845	        }
846	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
847	            .filter(existing -> !isDeleted(existing))
848	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
849	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
850	            .max();
851	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
852	    }
853	
854	    /**
855	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
856	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
857	     * name is normalized for case- and whitespace-insensitive comparison (see
858	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
859	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
860	     * regardless of creation order, making them members of one household.
861	     *
862	     * @param lastName the owner's last name
863	     * @param postcode the owner's postcode, may be {@code null}
864	     * @return the deterministic household identifier
865	     */
866	    private String householdId(String lastName, String postcode) {
867	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
868	        try {
869	            byte[] digest = MessageDigest.getInstance("SHA-256")
870	                .digest(key.getBytes(StandardCharsets.UTF_8));
871	            StringBuilder hex = new StringBuilder();
872	            for (int i = 0; i < 6; i++) {
873	                hex.append(String.format("%02x", digest[i]));
874	            }
875	            return hex.toString();
876	        } catch (NoSuchAlgorithmException ex) {
877	            throw new IllegalStateException("SHA-256 not available", ex);
878	        }
879	    }
880	
881	    /**
882	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
883	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
884	     * result is lower-cased. A {@code null} value normalizes to the empty string.
885	     *
886	     * @param value the value to normalize, may be {@code null}
887	     * @return the normalized value
888	     */
889	    private String normalizeForComparison(String value) {
890	        if (value == null) {
891	            return "";
892	        }
893	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
894	    }
895	
896	    /**
897	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
898	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
899	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
900	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
901	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
902	     * that is stored, returned, and used for every address comparison (household duplicate detection
903	     * and the shared household id).
904	     *
905	     * @param address the raw address value from the submitted owner payload, may be {@code null}
906	     * @return the normalized address
907	     */
908	    /**
909	     * Applies address normalization to the owner and derives the composed {@code address}, preferring
910	     * the structured fields over the flat {@code address} input for backward compatibility. When a
911	     * non-blank {@code addressLine1} is supplied, both structured lines are normalized (see
912	     * {@link #normalizeAddress}) and stored, and the composed {@code address} becomes the normalized
913	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
914	     * {@code addressLine2} was supplied. Otherwise the flat {@code address} is normalized and stored, and
915	     * the structured lines are cleared. The stored {@code address} is the form every later step reads.
916	     *
917	     * @param owner the owner being created, whose raw address fields are normalized in place
918	     */
919	    private void applyAddress(Owner owner) {
920	        String line1 = owner.getAddressLine1();
921	        if (line1 != null && !line1.isBlank()) {
922	            String normalizedLine1 = normalizeAddress(line1);
923	            String normalizedLine2 = normalizeAddress(owner.getAddressLine2());
924	            owner.setAddressLine1(normalizedLine1);
925	            if (!normalizedLine2.isEmpty()) {
926	                owner.setAddressLine2(normalizedLine2);
927	                owner.setAddress(normalizedLine1 + " " + normalizedLine2);
928	            } else {
929	                owner.setAddressLine2(null);
930	                owner.setAddress(normalizedLine1);
931	            }
932	        } else {
933	            owner.setAddressLine1(null);
934	            owner.setAddressLine2(null);
935	            owner.setAddress(normalizeAddress(owner.getAddress()));
936	        }
937	    }
938	
939	    private String normalizeAddress(String address) {
940	        if (address == null) {
941	            return "";
942	        }
943	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
944	        if (collapsed.isEmpty()) {
945	            return "";
946	        }
947	        String[] tokens = collapsed.split(" ");
948	        StringBuilder normalized = new StringBuilder();
949	        for (int i = 0; i < tokens.length; i++) {
950	            if (i > 0) {
951	                normalized.append(' ');
952	            }
953	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
954	        }
955	        return normalized.toString();
956	    }
957	}
