53	     * registration date: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
54	     * {@code SENIOR} at 65 or older. Returns {@code null} when the birth date or registration
55	     * date is absent, so an owner created without a birth date carries no age band.
56	     */
57	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum ageBand(Owner owner) {
58	        java.time.LocalDate birthDate = owner.getBirthDate();
59	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
60	        if (birthDate == null || registrationDate == null) {
61	            return null;
62	        }
63	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
64	        if (age < 18) {
65	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
66	        }
67	        if (age < 65) {
68	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
69	        }
70	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
71	    }
72	
73	    /**
74	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
75	     * in the owner's customer code. Returns {@code null} when the customer code is absent.
76	     */
77	    default Integer checkDigit(Owner owner) {
78	        String customerCode = owner.getCustomerCode();
79	        if (customerCode == null) {
80	            return null;
81	        }
82	        int sum = 0;
83	        boolean dbl = true;
84	        for (int i = customerCode.length() - 1; i >= 0; i--) {
85	            char c = customerCode.charAt(i);
86	            if (c < '0' || c > '9') {
87	                continue;
88	            }
89	            int d = c - '0';
90	            if (dbl) {
91	                d *= 2;
92	                if (d > 9) {
93	                    d -= 9;
94	                }
95	            }
96	            sum += d;
97	            dbl = !dbl;
98	        }
99	        return (10 - (sum % 10)) % 10;
100	    }
101	
102	    /**
103	     * Derives the owner's duplicate-detection identity key, formatted
104	     * {@code '<normalizedTelephone>|<email>|<householdId>'}. The email and household-id segments are
105	     * empty when the respective field is absent. The telephone and email are already stored in their
106	     * normalized (E.164 / lower-cased) form, so the stored values are used directly. This is the single
107	     * key against which owner duplicates are detected: two owners collide only when their whole keys
108	     * match.
109	     */
110	    default String identityKey(Owner owner) {
111	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
112	        String email = owner.getEmail() == null ? "" : owner.getEmail();
113	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
114	        return telephone + "|" + email + "|" + householdId;
115	    }
116	
117	    /**
118	     * Fixed city-to-region table used to derive an owner's locality.
119	     */
120	    java.util.Map<String, String> CITY_REGION =
121	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
122	
123	    /**
124	     * Inclusive 4-digit postcode range {@code [low, high]} owned by each region: NSW 2000-2099,
125	     * VIC 3000-3099, QLD 4000-4099. Used to resolve an owner's region from the postcode first.
126	     */
127	    java.util.Map<String, int[]> REGION_POSTCODES =
128	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
129	
130	    /**
131	     * Derives the owner's locality, the {@code REGION} segment of the owner's customer code (the
132	     * region-and-hash identity {@code '<REGION>-<HASH8>'}). Only when no customer code is present does
133	     * it fall back to deriving the region directly, preferring the postcode's {@link #REGION_POSTCODES}
134	     * range and then the fixed {@link #CITY_REGION} city table. Returns the canonical region string, or
135	     * {@code "UNKNOWN"} when neither source resolves a region.
136	     */
137	    default String locality(Owner owner) {
138	        String customerCode = owner.getCustomerCode();
139	        if (customerCode != null) {
140	            int dash = customerCode.indexOf('-');
141	            String region = dash >= 0 ? customerCode.substring(0, dash) : customerCode;
142	            if (!region.isEmpty()) {
143	                return region;
144	            }
145	        }
146	        String postcode = owner.getPostcode();
147	        if (postcode != null) {
148	            try {
149	                int value = Integer.parseInt(postcode.trim());
150	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
151	                    int[] range = entry.getValue();
152	                    if (value >= range[0] && value <= range[1]) {
153	                        return entry.getKey();
154	                    }
155	                }
156	            }
157	            catch (NumberFormatException ex) {
158	                // Not a numeric postcode; fall back to the city table below.
159	            }
160	        }
161	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
162	    }
