164	    /**
165	     * Fixed region-to-timezone table used to derive an owner's timezone as an IANA name.
166	     */
167	    java.util.Map<String, String> REGION_TIMEZONE =
168	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
169	
170	    /**
171	     * Derives the owner's timezone as an IANA name from the owner's {@link #locality(Owner) locality}
172	     * (region) via the fixed {@link #REGION_TIMEZONE} table: {@code NSW -> Australia/Sydney},
173	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}. Returns {@code null} when
174	     * the region does not resolve to a known timezone (e.g. the locality is {@code "UNKNOWN"}).
175	     */
