193	    default String telephoneDisplay(Owner owner) {
194	        String telephone = owner.getTelephone();
195	        if (telephone == null) {
196	            return null;
197	        }
198	        if (!telephone.startsWith("+")) {
199	            return telephone;
200	        }
201	        String digits = telephone.substring(1);
202	        if (!digits.chars().allMatch(Character::isDigit)) {
203	            return telephone;
204	        }
205	        String countryCode = "";
206	        for (String code : TELEPHONE_COUNTRY_CODES) {
207	            if (digits.startsWith(code) && digits.length() > code.length()) {
208	                countryCode = code;
209	                break;
210	            }
211	        }
212	        String national = digits.substring(countryCode.length());
213	        StringBuilder grouped = new StringBuilder();
214	        for (int i = 0; i < national.length(); i++) {
215	            if (i > 0 && i % 3 == 0) {
216	                grouped.append(' ');
217	            }
