237	     * year is earlier than the current date's fiscal year).
238	     */
239	    default Integer membershipPoints(Owner owner) {
240	        Integer namesakeCount = owner.getNamesakeCount();
241	        String email = owner.getEmail();
242	        Integer householdSize = owner.getHouseholdSize();
243	        int points = 0;
244	        if (email != null && !email.isBlank()) {
245	            points += 2;
246	        }
247	        if (namesakeCount != null && namesakeCount == 0) {
248	            points += 1;
249	        }
250	        if (householdSize != null && householdSize >= 3) {
251	            points += 2;
252	        }
253	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
254	        boolean hasTenure = registrationDate != null
255	            && fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate) >= 1;
256	        if (hasTenure) {
257	            points += 3;
258	        }
259	        return points;
260	    }
