262	    /**
263	     * Derives the owner's membership level, a number from 1 to 4, from the owner's
264	     * {@link #membershipPoints(Owner) membership points}: level {@code 1} for {@code 0-1} points,
265	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
266	     *
267	     * <p>The derived level is then capped by the owner's {@code membershipLevelCap} when one was
268	     * snapshotted at creation: a new owner's membership level cannot exceed one above the highest
269	     * membership level among their existing household members. When no cap is present (the owner had no
270	     * existing household member) the derived level is returned unchanged.
271	     */
272	    default Integer membershipLevel(Owner owner) {
273	        int points = membershipPoints(owner);
274	        int level;
275	        if (points <= 1) {
276	            level = 1;
