     * Handles {@link OwnerCityCapacityExceededException} raised when an owner is created in a city
     * that already contains the maximum number of owners (50 or more). Returns a 409 Conflict.
     *
     * @param e The {@link OwnerCityCapacityExceededException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
     */
    @ExceptionHandler(OwnerCityCapacityExceededException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleOwnerCityCapacityExceededException(OwnerCityCapacityExceededException e, HttpServletRequest request) {
        logger.debug("Owner city at capacity at {} {}: {}",
            request.getMethod(),
            request.getRequestURI(),
            e.getCity());
        HttpStatus status = HttpStatus.CONFLICT;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CONFLICT);
        detail.setProperty("errors", List.of("city"));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link DailyOwnerLimitExceededException} raised when an owner is created on a day that
     * has already reached the maximum number of owner registrations (100 or more). Returns a 429 Too
     * Many Requests.
     *
     * @param e The {@link DailyOwnerLimitExceededException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
     */
    @ExceptionHandler(DailyOwnerLimitExceededException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
        logger.debug("Daily owner limit reached at {} {}: {}",
            request.getMethod(),
            request.getRequestURI(),
            e.getRegistrationDate());
        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_RATE_LIMIT);
        detail.setProperty("errors", List.of("registrationDate"));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link FutureRegistrationDateException} raised when an owner is created with a supplied
     * {@code registrationDate} that is later than the server's current date. Returns a 400 Bad Request.
     *
     * @param e The {@link FutureRegistrationDateException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
     */
    @ExceptionHandler(FutureRegistrationDateException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
        logger.debug("Future registration date at {} {}: {}",
            request.getMethod(),
            request.getRequestURI(),
            e.getRegistrationDate());
        HttpStatus status = HttpStatus.BAD_REQUEST;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
        detail.setProperty("errors", List.of("registrationDate"));
        return ResponseEntity.status(status).body(detail);
    }

}

